import React from 'react';
import './Navbar.css';

function Navbar() {
  return (
    <nav className="navbar">
      <div className="navbar-brand">
        <span className="navbar-logo">📚</span>
        <span className="navbar-title">Library of the Jungle</span>
      </div>
    </nav>
  );
}

export default Navbar;
